use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::fs;
const R:&str="/home/ubuntu/src/zopro-perf-work/first48-redc176";
fn hash(p:&str)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn read(p:&str)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn inverse(p:u64,radix:u64)->u64{(1..radix).find(|v|v*p%radix==1).unwrap()}
// Independent whole-integer CIOS: no limb arrays, canceled-low identity or producer code.
fn toy(a:u64,b:u64,c:u64,d:u64,p:u64,fused:bool,first:bool)->u64{let mut t=0;let mut off=0;for row in 0..3{let w=if(first&&row==0)||(!first&&row==2){2}else{4};let base=1<<w;let bi=(b>>off)&(base-1);let di=(d>>off)&(base-1);t+=a*bi+if fused{c*di}else{0};let q=(base-t%base)*inverse(p,base)%base;t=(t+p*q)/base;off+=w;}assert_eq!(off,10);t}
fn main(){let pins=read(&format!("{R}/pins.json"));let mut checked=0;for(p,h)in pins.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());checked+=1;}
let result=read(&format!("{R}/result.json"));assert_eq!(result["math_pass"],true);assert_eq!(result["selects_native"],false);assert_eq!(result["SDK_requests"],0);let mut outputs=0u64;let mut rows=0u64;for field in result["fields"].as_array().unwrap(){let count=field["outputs"].as_u64().unwrap();let sum:u64=field["cohorts"].as_array().unwrap().iter().map(|x|x["outputs"].as_u64().unwrap()).sum();assert_eq!(count,sum);assert_eq!(count,57856);assert_eq!(field["row_checks"].as_u64().unwrap(),count*5);outputs+=count;rows+=count*5;}
let dags=result["dependency_models"].as_array().unwrap();for i in 0..4{let fused=i>=2;let first=i%2==1;assert_eq!(dags[i]["first48"],first);assert_eq!(dags[i]["fused"],fused);assert_eq!(dags[i]["IFMA_sites"],if fused{150}else{100});let codec=if fused{32}else{16};assert_eq!(dags[i]["ALU_sites"],50+if first{codec}else{0});}assert!(dags[1]["output_ready_score"].as_u64()>dags[0]["output_ready_score"].as_u64());assert!(dags[3]["output_ready_score"].as_u64()>dags[2]["output_ready_score"].as_u64());
let mut toy_pairs=0u64;for p in(3..64).step_by(2){let pi=inverse(p,1024);for a in 0..=2*p{for b in 0..=2*p{let raw=a*b;let q=(1024-raw%1024)*pi%1024;let want=(raw+p*q)/1024;for first in[false,true]{assert_eq!(toy(a,b,0,0,p,false,first),want);}toy_pairs+=1;}}}
let mut toy_fused=0u64;for p in[3,5,7]{let pi=inverse(p,1024);for a in 0..=2*p{for b in 0..=2*p{for c in 0..=2*p{for d in 0..=2*p{let raw=a*b+c*d;let q=(1024-raw%1024)*pi%1024;let want=(raw+p*q)/1024;for first in[false,true]{assert_eq!(toy(a,b,c,d,p,true,first),want);}toy_fused+=1;}}}}}
for step in["build-first48-exact-model","execute-first48-exact-model"]{let base=format!("{R}/workflow-fixed-types/{step}");let exit=read(&format!("{base}/exit.json"));assert_eq!(exit["returncode"],0);assert_eq!(exit["success"],true);for stream in["stdout","stderr"]{assert_eq!(hash(&format!("{base}/{stream}.log")),exit[format!("{stream}_sha256")].as_str().unwrap());}}assert_eq!(read(&format!("{R}/workflow-fixed-types/result.json"))["status"],"complete");let failed=fs::read_to_string(format!("{R}/workflow/build-first48-exact-model/stderr.log")).unwrap();assert!(failed.contains("type annotations needed"));
let out=json!({"passed":true,"pin_count":checked,"producer_outputs":outputs,"producer_row_checks":rows,"independent_reduced_radix_ordinary_pairs":toy_pairs,"independent_reduced_radix_fused_tuples":toy_fused,"two_orders_each":true,"source_instruction_counts_checked":true,"dependency_score_graph_shared_with_producer":true,"production_source176_unchanged":true,"decision":"close_fixed_first48_recipe_before_native","accepted_SDK_unchanged":true,"proof_ledger_unchanged":38668});fs::write(format!("{R}/review.json"),serde_json::to_vec_pretty(&out).unwrap()).unwrap();println!("{}",out);}
